import React from "react";
import "./JobItem.css";

const JobItem = ({ job, updateStatus, deleteJob }) => {
  const handleUpdate = () => {
    const newStatus = prompt("Update job status:", job.status);
    if (newStatus && updateStatus) {
      updateStatus(job._id, newStatus);
    }
  };

  const handleDelete = () => {
    if (window.confirm("Are you sure you want to delete this job?") && deleteJob) {
      deleteJob(job._id);
    }
  };

  return (
    <div className="job-item">
      <div className="job-header">
        <h3>{job.company}</h3>
        <p className="job-position">{job.position || "No position specified"}</p>
      </div>
      <div className="job-details">
        <p><strong>Date:</strong> {new Date(job.date).toLocaleDateString()}</p>
        <p><strong>Status:</strong> {job.status}</p>
        {job.link && (
          <p>
            <strong>Link:</strong>{" "}
            <a href={job.link} target="_blank" rel="noopener noreferrer">
              View Job Application
            </a>
          </p>
        )}
      </div>
      <div className="job-actions">
        <button className="update-btn" onClick={handleUpdate}>Update</button>
        <button className="delete-btn" onClick={handleDelete}>Delete</button>
      </div>
    </div>
  );
};

export default JobItem;
